import{addFlash,addPopup,addRing,BONUS_Y}from"./fx.js";import{addParticle}from"./particles.js";import{count,powerColor,smoke,sparks}from"./emit.js";const POINTS="#fff6c8",STREAK=.5,TAIL=5,LAG=.03,FADE=.35,GLOW_R=70,GLOW_R_STEP=7,GLOW_R_MAX=1.5*GLOW_R,GLOW_ALPHA=.7,GLOW_ALPHA_STEP=.1,BONUS_GAP=64,offBonus=y=>Math.abs(y-BONUS_Y)>=BONUS_GAP?y:y<BONUS_Y?BONUS_Y-BONUS_GAP:BONUS_Y+BONUS_GAP;function pickup(fx,ev,rng){const color=powerColor(ev.kind);addRing(fx,{x:ev.x,y:ev.y,maxR:90,color,life:.4}),sparks(fx,rng,ev.x,ev.y,8,260,[color,"#ffffff"]);const text=ev.kind==="bomb"?"+1 BOMB":String(ev.kind).toUpperCase();addPopup(fx,{x:ev.x,y:ev.y-24,text,color,scale:1.3,life:1.2}),addPopup(fx,{x:ev.x,y:ev.y-70,text:"+"+ev.points,points:!0,color:POINTS,life:1.2})}function sweep(fx,ev,rng,world){const color=powerColor(ev.kind);addPopup(fx,{x:ev.x,y:offBonus(ev.y-24),text:"+"+ev.points,points:!0,color:POINTS,scale:1.2,life:1.4});const ship=world?.ship;if(!ship)return;const vx=(ship.x-ev.x)/STREAK,vy=(ship.y-ev.y)/STREAK;addParticle(fx,{x:ev.x,y:ev.y,vx,vy,life:STREAK,size:4,color:"#ffffff",kind:"spark",additive:!0});for(let i=0,m=count(fx,TAIL);i<m;i++){const lag=(i+1)*LAG;addParticle(fx,{x:ev.x-vx*lag,y:ev.y-vy*lag,vx,vy,life:STREAK+lag,size:3.4-i*.5,color,kind:"ember",additive:!0})}shipGlow(fx,ship,color,ev.nth)}const glowAt=nth=>({r:Math.min(GLOW_R_MAX,GLOW_R+GLOW_R_STEP*nth),alpha:Math.min(1,GLOW_ALPHA+GLOW_ALPHA_STEP*nth)});function shipGlow(fx,ship,color,nth){const glow=nth>0&&fx.flashes.find(f=>f.tag==="sweep");if(glow){Object.assign(glow,glowAt(nth));return}const life=STREAK+FADE;addFlash(fx,{x:ship.x,y:ship.y,...glowAt(nth),color,ramp:STREAK/life,life,tag:"sweep"})}function power(fx,ev,rng,world){const ship=world?.ship;ship&&(ev.on?addRing(fx,{x:ship.x,y:ship.y,maxR:140,color:powerColor(ev.kind),life:.5}):smoke(fx,rng,ship.x,ship.y,3,14,10))}function bulletTime(fx,ev){fx.bulletTime=!!ev.on,addFlash(fx,{full:!0,color:"#3affc8",alpha:ev.on?.3:.15,life:.3,tag:"bullettime"})}export const WORLD={pickup,sweep,power,bulletTime};
